function maxOf(arr) {
  if (arr.length === 0) return null; // empty-array edge case
  let best = arr[0]; // seed accumulator with first element
  for (let i = 1; i < arr.length; i++) {
    if (arr[i] > best) best = arr[i]; // update running max
  }
  return best;
}
console.log(maxOf([3, 7, 2, 9, 1]));

